<script setup>
import { computed, onMounted, ref, watch } from 'vue';
import { Users, UserCheck, UserPlus, Activity, ChartNoAxesCombined, Target, Download, TrendingUp, Trophy, Lightbulb, RefreshCw } from 'lucide-vue-next';
import { useAuthStore } from '~/stores/api/auth';
import { useAdminAnalyticsStore } from '~/stores/api/adminAnalytics';
import { canAccessPage } from '~/utils/roles';
import Panel from '~/components/analytics/Panel.vue';
import LineChart from '~/components/analytics/LineChart.vue';
import DonutChart from '~/components/analytics/DonutChart.vue';
import BarChart from '~/components/analytics/BarChart.vue';
import RadarChart from '~/components/analytics/RadarChart.vue';
import HeatmapChart from '~/components/analytics/HeatmapChart.vue';

const auth = useAuthStore(); const store = useAdminAnalyticsStore();
const ready = ref(false); const campuses = ref([]); const programs = ref([]); const provinces = ref([]);
const input = 'min-w-0 w-full rounded-2xl border border-outline-variant bg-surface-container-low px-3 py-2.5 font-body-sm text-body-sm text-on-surface outline-none focus:border-primary-container';
const format = value => value == null ? '—' : Number(value).toLocaleString('id-ID', { maximumFractionDigits: 1 });
const shortDate = value => value ? new Date(value).toLocaleDateString('id-ID', { day: 'numeric', month: 'short' }) : '—';
const metrics = computed(() => [
  { label:'Total Users',value:store.overview?.total_users,icon:Users,tone:'bg-pale-blue text-primary-container',note:'Siswa dan tutor' },
  { label:'User Aktif',value:store.overview?.active_users,icon:UserCheck,tone:'bg-success-soft text-success-emerald',note:'Mencatat rekap pada periode' },
  { label:'User Baru',value:store.overview?.new_users,icon:UserPlus,tone:'bg-soft-orange text-on-secondary-container',note:store.overview?.new_users_change_percent == null ? 'Periode terpilih' : `${store.overview.new_users_change_percent>0?'+':''}${store.overview.new_users_change_percent}% vs periode sebelumnya` },
  { label:'Aktivitas Belajar',value:null,icon:Activity,tone:'bg-pale-blue text-primary-container',note:'Belum tercatat' },
  { label:'Rata-rata Skor Tryout',value:store.overview?.average_score,icon:ChartNoAxesCombined,tone:'bg-success-soft text-success-emerald',note:'Rekap eksternal pada periode' },
  { label:'Rata-rata Akurasi',value:null,icon:Target,tone:'bg-soft-orange text-on-secondary-container',note:'Belum tercatat' },
]);
const roles = computed(() => (store.roleDistribution || []).map(x => ({ label: Number(x.role)===2?'Siswa':'Tutor', total:x.total })));
const subtests = computed(() => Object.entries(store.subtests || {}).filter(([,v]) => v != null).map(([label,total]) => ({ label:label.toUpperCase(), total:Number(total) })).sort((a,b) => b.total-a.total));
const scoreBuckets = computed(() => store.scoreDistribution || []);
const topBucket = computed(() => scoreBuckets.value.reduce((best,row) => Number(row.total)>Number(best?.total||0)?row:best,null));
const funnelMax = computed(() => Math.max(1,...(store.funnel||[]).map(x => Number(x.total)||0)));
async function loadMasters() {
  const results = await Promise.allSettled([store.request('/kampus'), store.request('/wilayah/provinsi')]);
  campuses.value = results[0].status==='fulfilled' ? results[0].value?.data || [] : [];
  provinces.value = results[1].status==='fulfilled' ? results[1].value?.data || [] : [];
}
watch(() => store.filters.campus_id, async id => {
  store.filters.prodi_code = ''; programs.value = [];
  if (!id) return;
  try { const result = await store.request(`/admin/campuses/${id}/prodi`, { query:{ limit:100 } }); programs.value = result?.data || []; } catch { programs.value = []; }
});
watch(() => store.filters.period, period => {
  if (period !== 'custom') { store.filters.date_from = ''; store.filters.date_to = ''; }
});
function applyFilters() { store.fetchAllAnalytics(); }
async function retry(key) { try { await store.fetchEndpoint(key); store.widgetErrors[key] = ''; } catch { store.widgetErrors[key] = 'Gagal memuat data.'; } }
onMounted(async () => {
  auth.initializeAuth(); if (!auth.token) return navigateTo('/login');
  const user = await auth.fetchCurrentUser();
  if (Number(user?.role)!==1 || !canAccessPage(user?.role,'analytics.read')) return navigateTo('/dashboard');
  ready.value=true; await Promise.all([store.fetchAllAnalytics(),loadMasters()]);
});
</script>

<template>
  <div class="mx-auto w-full max-w-[1700px] min-w-0 px-4 py-5 sm:px-6 sm:py-7 lg:px-8">
    <template v-if="ready && Number(auth.user?.role)===1">
      <header class="mb-5 flex flex-wrap items-start justify-between gap-4"><div><h1 class="font-headline-md text-headline-md text-on-surface">Analytics</h1><p class="mt-1 max-w-3xl font-body-sm text-body-sm text-on-surface-variant">Pantau pertumbuhan pengguna, aktivitas belajar, perkembangan skor, performa subtes, dan engagement MatrIQ.</p></div><NuxtLink to="/reports?type=analytics" class="inline-flex items-center gap-2 rounded-2xl bg-primary-container px-4 py-2.5 font-label-sm text-label-sm text-white hover:bg-brand-700"><Download class="h-4 w-4" />Export Report</NuxtLink></header>
      <div v-if="store.error" role="alert" class="mb-5 flex items-center gap-3 rounded-2xl border border-soft-blue bg-surface-white p-4"><span class="flex-1">{{ store.error }}</span><button class="inline-flex items-center gap-2 text-primary-container" @click="store.fetchAllAnalytics()"><RefreshCw class="h-4 w-4" />Coba Lagi</button></div>
      <section class="mb-6 rounded-3xl border border-soft-blue bg-surface-white p-4 shadow-sm sm:p-5" aria-label="Filter analytics"><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-7"><label><span class="sr-only">Periode</span><select v-model="store.filters.period" :class="input"><option value="7d">7 Hari</option><option value="30d">30 Hari</option><option value="3m">3 Bulan</option><option value="6m">6 Bulan</option><option value="1y">1 Tahun</option><option value="custom">Custom</option></select></label><label><span class="sr-only">Role</span><select v-model="store.filters.role" :class="input"><option value="">Semua User</option><option value="2">Siswa</option><option value="3">Tutor</option></select></label><label><span class="sr-only">Provinsi</span><select v-model="store.filters.province" :class="input"><option value="">Semua Provinsi</option><option v-for="province in provinces" :key="province.kode" :value="province.nama">{{ province.nama }}</option></select></label><label><span class="sr-only">Kampus Target</span><select v-model="store.filters.campus_id" :class="input"><option value="">Semua Kampus</option><option v-for="campus in campuses" :key="campus.id" :value="campus.id">{{ campus.nama }}</option></select></label><label><span class="sr-only">Program Studi</span><select v-model="store.filters.prodi_code" :disabled="!store.filters.campus_id" :class="input"><option value="">{{ store.filters.campus_id ? 'Semua Prodi' : 'Pilih kampus dulu' }}</option><option v-for="program in programs" :key="program.kode_snbt" :value="program.kode_snbt">{{ program.nama }}</option></select></label><label v-if="store.filters.period==='custom'"><span class="sr-only">Dari tanggal</span><input v-model="store.filters.date_from" type="date" :class="input" /></label><label v-if="store.filters.period==='custom'"><span class="sr-only">Sampai tanggal</span><input v-model="store.filters.date_to" type="date" :class="input" /></label><button class="rounded-2xl border border-primary-container px-4 py-2.5 font-label-sm text-label-sm text-primary-container hover:bg-pale-blue" @click="applyFilters">Terapkan</button></div></section>
      <h2 class="mb-3 font-title-md text-title-md text-on-surface">Overview</h2>
      <section class="mb-7 grid gap-3 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-6" aria-label="Metrik utama"><article v-for="metric in metrics" :key="metric.label" class="rounded-3xl border border-soft-blue bg-surface-white p-4 shadow-sm"><div class="mb-3 flex h-10 w-10 items-center justify-center rounded-2xl" :class="metric.tone"><component :is="metric.icon" class="h-5 w-5" /></div><p class="font-caption text-caption text-outline">{{ metric.label }}</p><div v-if="store.loading" class="mt-2 h-7 w-16 animate-pulse rounded-lg bg-surface-container" /><p v-else class="mt-1 font-title-md text-title-md text-on-surface">{{ format(metric.value) }}</p><p class="mt-2 text-xs text-on-surface-variant">{{ metric.note }}</p></article></section>
      <h2 class="mb-3 font-title-md text-title-md text-on-surface">Pertumbuhan &amp; Engagement</h2>
      <div class="mb-7 grid min-w-0 gap-5 lg:grid-cols-12"><Panel class="lg:col-span-8" title="Pertumbuhan Pengguna" subtitle="Pendaftaran harian siswa dan tutor" :loading="store.loading" :error="store.widgetErrors.userGrowth" @retry="retry('userGrowth')"><LineChart :rows="store.userGrowth || []" :series="[{key:'students',label:'Siswa'},{key:'tutors',label:'Tutor'},{key:'total',label:'Total'}]" area /></Panel><Panel class="lg:col-span-4" title="Distribusi Role" subtitle="Siswa dan tutor dalam filter" :loading="store.loading" :error="store.widgetErrors.roleDistribution" @retry="retry('roleDistribution')"><DonutChart :rows="roles" center-label="User" /></Panel><Panel class="lg:col-span-8" title="User Aktif (Proxy Rekap)" subtitle="DAU, WAU, MAU berdasarkan user unik yang mencatat hasil tryout" :loading="store.loading" :error="store.widgetErrors.activeTrend" @retry="retry('activeTrend')"><LineChart :rows="store.activeTrend || []" :series="[{key:'dau',label:'DAU'},{key:'wau',label:'WAU'},{key:'mau',label:'MAU'}]" /></Panel><Panel class="lg:col-span-4" title="Funnel Pengguna" subtitle="Tahap yang terukur dari akun, onboarding, dan rekap" :loading="store.loading" :error="store.widgetErrors.funnel" @retry="retry('funnel')"><div v-if="!store.funnel?.length" class="py-12 text-center text-on-surface-variant">Belum cukup data.</div><div v-else class="space-y-3"><div v-for="step in store.funnel" :key="step.label" :title="`${step.label}: ${step.total}`"><div class="mb-1 flex justify-between gap-2 text-sm"><span>{{ step.label }}</span><strong>{{ format(step.total) }}</strong></div><div class="h-3 rounded-full bg-surface-container"><div class="h-3 rounded-full bg-primary-container" :style="{ width:`${100*Number(step.total)/funnelMax}%` }" /></div></div></div></Panel><Panel class="lg:col-span-8" title="Pola Pencatatan Rekap" subtitle="Hari dan jam user mencatat hasil tryout eksternal" :loading="store.loading" :error="store.widgetErrors.activityHeatmap" @retry="retry('activityHeatmap')"><HeatmapChart :rows="store.activityHeatmap || []" /></Panel><Panel class="lg:col-span-4" title="Aktivitas Belajar &amp; Waktu" subtitle="Belum ada tabel sesi belajar atau waktu belajar" :loading="store.loading"><div class="flex h-40 items-center justify-center rounded-2xl bg-surface-container-low p-5 text-center text-on-surface-variant">{{ store.studyProgress?.reason || 'Data aktivitas belajar belum tersedia.' }}</div></Panel></div>
      <h2 class="mb-3 font-title-md text-title-md text-on-surface">Performa Akademik &amp; Tryout</h2>
      <div class="mb-7 grid min-w-0 gap-5 lg:grid-cols-12"><Panel class="lg:col-span-8" title="Perkembangan Skor Tryout" subtitle="Rata-rata, median, dan rata-rata 10% skor tertinggi per hari" :loading="store.loading" :error="store.widgetErrors.tryoutTrend" @retry="retry('tryoutTrend')"><LineChart :rows="store.tryoutTrend || []" :series="[{key:'average_score',label:'Rata-rata'},{key:'median_score',label:'Median'},{key:'top_ten_average',label:'Top 10%'}]" /></Panel><Panel class="lg:col-span-4" title="Platform Tryout" subtitle="Sumber rekap eksternal pada periode" :loading="store.loading" :error="store.widgetErrors.platformStats" @retry="retry('platformStats')"><DonutChart :rows="store.platformStats || []" center-label="Rekap" /></Panel><Panel class="lg:col-span-6" title="Distribusi Skor" subtitle="Jumlah rekap pada tiap rentang skor" :loading="store.loading" :error="store.widgetErrors.scoreDistribution" @retry="retry('scoreDistribution')"><BarChart :rows="scoreBuckets" /><p v-if="Number(topBucket?.total)>0" class="mt-4 text-xs text-on-surface-variant">Konsentrasi tertinggi: {{ topBucket.label }} ({{ topBucket.total }} rekap).</p></Panel><Panel class="lg:col-span-6" title="Performa Subtes" subtitle="Radar rata-rata skor tujuh subtes" :loading="store.loading" :error="store.widgetErrors.subtests" @retry="retry('subtests')"><RadarChart :rows="subtests" /></Panel><Panel class="lg:col-span-8" title="Rata-rata per Subtes" subtitle="Diurutkan dari skor tertinggi ke terendah" :loading="store.loading" :error="store.widgetErrors.subtests" @retry="retry('subtests')"><BarChart :rows="subtests" :max="1000" /></Panel><Panel class="lg:col-span-4" title="Terkuat &amp; Terlemah" subtitle="Berdasarkan rata-rata rekap eksternal" :loading="store.loading"><div v-if="!subtests.length" class="py-12 text-center text-on-surface-variant">Belum cukup data.</div><div v-else class="space-y-3"><div class="rounded-2xl bg-success-soft p-4"><p class="text-xs text-on-surface-variant">Subtes Terkuat</p><strong class="font-title-md text-title-md text-success-emerald">{{ subtests[0].label }} · {{ format(subtests[0].total) }}</strong></div><div class="rounded-2xl bg-soft-orange p-4"><p class="text-xs text-on-surface-variant">Subtes Terlemah</p><strong class="font-title-md text-title-md text-on-secondary-container">{{ subtests[subtests.length-1].label }} · {{ format(subtests[subtests.length-1].total) }}</strong></div></div></Panel><Panel class="lg:col-span-12" title="Akurasi &amp; Waktu Belajar" subtitle="Grafik akurasi, soal dikerjakan, dan durasi belajar menunggu pencatatan aktivitas belajar" :loading="store.loading"><div class="grid gap-3 sm:grid-cols-3"><div v-for="label in ['Progress Latihan','Distribusi Akurasi','Waktu Belajar']" :key="label" class="rounded-2xl border border-soft-blue bg-surface-container-low p-5 text-center"><p class="font-label-sm text-label-sm">{{ label }}</p><p class="mt-2 text-sm text-on-surface-variant">Data belum tersedia</p></div></div></Panel></div>
      <h2 class="mb-3 font-title-md text-title-md text-on-surface">Target &amp; Demografi</h2>
      <div class="mb-7 grid min-w-0 gap-5 lg:grid-cols-3"><Panel title="User per Provinsi" subtitle="10 provinsi terbanyak; nama dari master wilayah" :loading="store.loading" :error="store.widgetErrors.geography" @retry="retry('geography')"><BarChart :rows="store.geography || []" /></Panel><Panel title="Kampus Target Terpopuler" subtitle="Pilihan utama user" :loading="store.loading" :error="store.widgetErrors.campusTargets" @retry="retry('campusTargets')"><BarChart :rows="store.campusTargets || []" /></Panel><Panel title="Prodi Target Terpopuler" subtitle="Pilihan utama user" :loading="store.loading" :error="store.widgetErrors.programTargets" @retry="retry('programTargets')"><BarChart :rows="store.programTargets || []" /></Panel></div>
      <h2 class="mb-3 font-title-md text-title-md text-on-surface">Leaderboard &amp; Insight</h2>
      <div class="mb-7 grid min-w-0 gap-5 lg:grid-cols-2"><Panel title="Top Skor" subtitle="Skor terbaik unik per user pada periode" :loading="store.loading" :error="store.widgetErrors.leaderboard" @retry="retry('leaderboard')"><div v-if="!store.leaderboard?.length" class="py-12 text-center text-on-surface-variant">Belum cukup data.</div><div v-for="row in store.leaderboard || []" :key="row.user_id" class="flex items-center gap-3 border-b border-soft-blue py-3"><Trophy class="h-4 w-4 shrink-0 text-primary-container" /><span class="w-6 shrink-0 text-outline">#{{ row.rank }}</span><span class="min-w-0 flex-1"><strong class="block truncate">{{ row.nama }}</strong><small class="block truncate text-outline">{{ [row.campus_short||row.campus_name,row.prodi_name,row.platform].filter(Boolean).join(' · ') }}</small></span><strong class="text-primary-container">{{ format(row.best_score) }}</strong></div></Panel><Panel title="Peningkatan Skor Terbesar" subtitle="Skor terakhir dikurangi skor pertama; minimal dua rekap" :loading="store.loading" :error="store.widgetErrors.mostImproved" @retry="retry('mostImproved')"><div v-if="!store.mostImproved?.length" class="py-12 text-center text-on-surface-variant">Belum cukup data.</div><div v-for="row in store.mostImproved || []" :key="row.user_id" class="flex items-center gap-3 border-b border-soft-blue py-3"><TrendingUp class="h-4 w-4 shrink-0 text-success-emerald" /><span class="min-w-0 flex-1"><strong class="block truncate">{{ row.nama }}</strong><small class="block truncate text-outline">{{ [row.campus_short||row.campus_name,row.prodi_name].filter(Boolean).join(' · ') }}</small></span><span class="text-right"><strong :class="Number(row.improvement)>=0?'text-success-emerald':'text-danger-rose'">{{ Number(row.improvement)>0?'+':'' }}{{ format(row.improvement) }}</strong><small class="block text-outline">{{ format(row.first_score) }} → {{ format(row.latest_score) }}</small></span></div></Panel><Panel title="Aktivitas Terbaru" subtitle="Pencatatan rekap tryout eksternal" :loading="store.loading" :error="store.widgetErrors.recentActivity" @retry="retry('recentActivity')"><div v-if="!store.recentActivity?.length" class="py-12 text-center text-on-surface-variant">Belum ada aktivitas pada periode ini.</div><div v-for="(row,index) in store.recentActivity || []" :key="index" class="flex justify-between gap-3 border-b border-soft-blue py-3 text-sm"><span class="min-w-0"><strong class="block truncate">{{ row.nama }}</strong><small class="block truncate text-outline">{{ row.activity }} · {{ row.category }}</small></span><span class="shrink-0 text-outline">{{ shortDate(row.timestamp) }}</span></div></Panel><Panel title="Insight Otomatis" subtitle="Aturan sederhana yang dihitung dari data saat ini" :loading="store.loading" :error="store.widgetErrors.insights" @retry="retry('insights')"><div v-if="!store.insights?.length" class="py-12 text-center text-on-surface-variant">Belum cukup data untuk menghasilkan insight.</div><div v-for="(insight,index) in store.insights || []" :key="index" class="mb-3 flex gap-3 rounded-2xl bg-pale-blue p-4"><Lightbulb class="h-5 w-5 shrink-0 text-primary-container" /><p class="text-sm text-on-surface">{{ insight.text }}</p></div></Panel></div>
      <p class="mb-5 text-xs text-outline">Sumber: akun, profil dan target, serta rekap tryout eksternal. Data latihan, durasi belajar, dan akurasi belum tersedia; angka 0 tidak digunakan sebagai pengganti data yang tidak tercatat.</p>
    </template><div v-else class="h-40 animate-pulse rounded-3xl bg-surface-container" aria-label="Memuat analytics" />
  </div>
</template>
